<script lang="ts">import { BarChart, type BarChartBar } from '@microcks/deep-ink';const RUNS = Array.from({ length: 20 }, (_, i) => { const id = String(100 + i); const failed = i % 6 === 4; const ms = 700 + ((i * 337) % 1900); return { id, failed, ms }; }); let id = $state('104'); const bars: BarChartBar[] = RUNS.slice(0,8).map(r => ({ id:r.id,value:r.ms,tone:r.failed ? 'danger':'success',label:r.id,description:`Run #${r.id}, ${r.ms} ms` }));</script><div style="max-width:700px"><BarChart label="Last 8 runs" {bars} max={3000} selectedId={id} onselect={v => id = v} grid={[0.5,1]} ticks={['3 s','0']} ticksEnd={['SLA','']} minHeight={4} table={{caption:'Last 8 runs',columns:['Run','Duration'],rows:RUNS.slice(0,8).map(r => [`#${r.id}`,`${r.ms} ms`])}}>{#snippet overlay()}<span class="sb-note">Budget 2 s</span>{/snippet}</BarChart></div>
